bool seleccionar(std::span<int> total, std::span<int>& actual, int inicio, int cantidad) {
    if (inicio < 0 || cantidad < 0) {
        return false;
    }
    const auto posicion = static_cast<std::size_t>(inicio);
    const auto longitud = static_cast<std::size_t>(cantidad);
    if (posicion > total.size() || longitud > total.size() - posicion) {
        return false;
    }
    actual = total.subspan(posicion, longitud);
    return true;
}

int ajustar(std::span<int> vista, int ajuste) {
    if (vista.size() > 4) {
        return -1;
    }
    if (vista.empty()) {
        return 0;
    }
    if (ajuste < -3 || ajuste > 3) {
        return -1;
    }
    // Comprueba todos los datos y resultados antes de escribir.
    return -1;
}

int main() {
    std::array<int, 4> datos{2, 5, 8, 1};
    std::span<int> total{datos};
    std::span<int> actual;
    std::span<const int> guardada;
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) {
        return 1;
    }
    for (int orden = 0; orden < ordenes; ++orden) {
        int operacion = 0;
        int inicio = 0;
        int cantidad = 0;
        int ajuste = 0;
        if (!(std::cin >> operacion >> inicio >> cantidad >> ajuste)) {
            return 1;
        }
        std::string estado = "Orden";
        int resultado = -2;
        if (operacion == 1) {
            const bool aceptada = seleccionar(total, actual, inicio, cantidad);
            estado = aceptada ? "Seleccion" : "Rechazo";
            resultado = aceptada ? 1 : -1;
        } else if (operacion == 2) {
            guardada = actual;
            estado = "Guardada";
            resultado = 0;
        } else if (operacion == 3) {
            resultado = ajustar(actual, ajuste);
            estado = resultado < 0 ? "Rechazo" : resultado == 0 ? "Vacio" : "Cambio";
        } else if (operacion == 4) {
            actual = std::span<int>{};
            estado = "Vacio";
            resultado = 0;
        }
        std::cout << "Estado:" << estado << ";Resultado:" << resultado << ";Actual:" << actual.size() << '/';
        if (actual.empty()) {
            std::cout << 'X';
        } else {
            std::cout << actual[0];
        }
        std::cout << ";Guardada:" << guardada.size() << '/';
        if (guardada.empty()) {
            std::cout << 'X';
        } else {
            std::cout << guardada[0];
        }
        std::cout << ";Datos:" << datos[0] << ',' << datos[1] << ',' << datos[2] << ',' << datos[3] << '\n';
    }
    return 0;
